import { existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { expect, test, type Page } from "@playwright/test";

// The real models process each class on CPU: loading them and running every stage takes minutes.
const PROCESSING_TIMEOUT = 6 * 60_000;

// Two synthetic voices taking turns in Spanish, generated by `make e2e` with espeak-ng
// (backend/scripts/two-voices.sh). Not versioned: it is created at each run, with no real data.
const twoVoices = fileURLToPath(new URL("./generated/two-voices.ogg", import.meta.url));
// 61 seconds of a synthetic tone in Opus: real audio above the shortest duration, without voice.
const tone = fileURLToPath(new URL("./fixtures/synthetic-class.ogg", import.meta.url));

async function uploadAsTeacher(page: Page, audio: string) {
  await page.goto("/");
  await page.getByRole("button", { name: /docente de prueba/i }).click();

  await expect(page.getByRole("heading", { name: /sube una grabación/i })).toBeVisible();
  await page.getByLabel("Audio").setInputFiles(audio);
  await page.getByRole("button", { name: /enviar a procesar/i }).click();

  await expect(page.getByRole("heading", { name: /estamos preparando el repaso/i })).toBeVisible();
}

test("a teacher uploads a class of two voices and sees its transcript by speaker", async ({ page }) => {
  test.setTimeout(PROCESSING_TIMEOUT + 60_000);
  expect(existsSync(twoVoices), "run the tests with make e2e, which generates the audio").toBe(true);

  await uploadAsTeacher(page, twoVoices);
  await expect(page.getByText(/preparando el audio|transcribiendo|identificando voces|analizando el contenido/i).first()).toBeVisible();

  await expect(page.getByRole("heading", { name: /repaso de la clase/i })).toBeVisible({ timeout: PROCESSING_TIMEOUT });
  await expect(page.getByRole("heading", { name: "Transcripción" })).toBeVisible();
  // Two voices are found, each with its own interventions, and the words come from the audio.
  await expect(page.getByText("Hablante 1", { exact: true }).first()).toBeVisible();
  await expect(page.getByText("Hablante 2", { exact: true }).first()).toBeVisible();
  await expect(page.getByText("Hablante 3", { exact: true })).toHaveCount(0);
  await expect(page.getByText(/fracciones/i).first()).toBeVisible();
  // No pedagogical analysis until E4.
  await expect(page.getByText(/todavía no contiene elementos/i)).toBeVisible();

  await page.getByRole("button", { name: /aprobar resultado/i }).click();
  await expect(page.getByRole("status")).toHaveText(/resultado aprobado/i);
});

test("a teacher uploads a class without voice and sees that no voice was found", async ({ page }) => {
  test.setTimeout(PROCESSING_TIMEOUT + 60_000);

  await uploadAsTeacher(page, tone);

  await expect(page.getByRole("heading", { name: /repaso de la clase/i })).toBeVisible({ timeout: PROCESSING_TIMEOUT });
  await expect(page.getByText(/no se ha detectado voz/i)).toBeVisible();
});

test("a teacher sees a clear error when the uploaded audio is not admitted", async ({ page }) => {
  await page.goto("/");
  await page.getByRole("button", { name: /docente de prueba/i }).click();

  await expect(page.getByRole("heading", { name: /sube una grabación/i })).toBeVisible();
  // A text payload named .wav: the API rejects it by content, not by extension (contract 0.2).
  await page.getByLabel("Audio").setInputFiles({
    name: "not-audio.wav",
    mimeType: "audio/wav",
    buffer: Buffer.from("this is not an audio file"),
  });
  await page.getByRole("button", { name: /enviar a procesar/i }).click();

  await expect(page.getByRole("alert")).toHaveText(/formato del audio no está admitido/i);
  await expect(page.getByRole("heading", { name: /sube una grabación/i })).toBeVisible();
});
